@startuml

class GasStation {
  + ID : string
  + address : string
}

class FuelPump {
  + number : int
  + isSelfService : boolean
}

class Fuel {
  + name : string
  + octaneRating : int
}

class DailyPrice {
  + date : date
  + pricePerLiter : float
}

class FuelPurchase {
  + ID : string
  + litersDispensed : float
}

GasStation "1" *-- "1..12" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "1" -- "*" Fuel
FuelPump "1" -- "*" FuelPurchase
Fuel "1" -- "*" DailyPrice
Fuel "1" -- "*" FuelPurchase
DailyPrice "1" -- "1" FuelPurchase

@enduml

